/** Gibt genau einen reservierten Platz frei und aktualisiert die Mail im selben versionsgeschützten Commit. */
return $input.all().map((item, index) => {
  const counter = item.json;
  const failure = $('KI-Fehler vorbereiten').itemMatching(index).json;
  const count = Number(counter.fields?.reservedCount?.integerValue);
  if (!Number.isSafeInteger(count) || count < 1 || failure.quota?.state !== 'reserved') {
    throw new Error('Tagesplatz kann nicht freigegeben werden: Reservierung oder Zähler ungültig.');
  }
  if (counter.name !== failure.quota.counterName || !counter.updateTime || !failure.reservationUpdateTime) {
    throw new Error('Tagesplatz kann nicht freigegeben werden: Dokumentversion fehlt.');
  }
  return { json: { ...failure, commit: { writes: [
    { update: { name: counter.name, fields: { reservedCount: { integerValue: String(count - 1) } } },
      updateMask: { fieldPaths: ['reservedCount'] }, currentDocument: { updateTime: counter.updateTime } },
    { update: { name: failure.reservation.name, fields: {
        status: { stringValue: 'failed' }, quotaState: { stringValue: 'released' },
        failedAt: { timestampValue: failure.failedAt }, errorMessage: { stringValue: failure.errorMessage }
      } }, updateMask: { fieldPaths: ['status', 'quotaState', 'failedAt', 'errorMessage'] },
      currentDocument: { updateTime: failure.reservationUpdateTime } }
  ] } }, pairedItem: { item: index } };
});

/** Prüft das gelesene Kontingent und die Freigabe für dieses Ticket. */
function readQuota(counter, data) {
  const reserved = Number(counter.fields?.reservedCount?.integerValue);
  const completed = Number(counter.fields?.completedCount?.integerValue);
  const limit = Number(counter.fields?.dailyLimit?.integerValue);
  if (!Number.isSafeInteger(reserved) || reserved < 1 ||
      !Number.isSafeInteger(completed) || completed < 0 ||
      limit !== 10 || reserved + completed > limit ||
      data.quota?.state !== 'reserved' || data.validation?.valid !== true) {
    throw new Error('Ticketabschluss gestoppt: Tageszähler oder Ticket ungültig.');
  }
  return { reserved, completed };
}

/** Verhindert Schreibvorgänge ohne zugehörige Reservierung und Dokumentversion. */
function checkReservation(counter, data) {
  if (counter.name !== data.quota.counterName || !counter.updateTime ||
      !data.reservation?.updateTime || !/^[a-f0-9]{64}$/.test(data.reservationId)) {
    throw new Error('Ticketabschluss gestoppt: Reservierung oder Dokumentversion fehlt.');
  }
}

/** Verpackt Text im Werteformat der REST-Schnittstelle. */
function string(value) { return { stringValue: value }; }

/** Erstellt die im Board sichtbaren Ticketfelder. */
function boardFields(data, now) {
  return {
    title: string(data.ticket.title), description: string(data.emailBody + '\n\nDieses Ticket wurde KI-generiert.'),
    dueDate: data.ticket.deadline === null ? { nullValue: null } : string(data.ticket.deadline),
    category: string(data.ticket.category), priority: string(data.ticket.priority),
    status: string('triage'), assignedTo: { arrayValue: { values: [] } },
    subtasks: { arrayValue: { values: [] } },
    createdAt: string(now), updatedAt: string(now),
  };
}

/** Erhält Absender und Originaldaten für Zuordnung und Nachbearbeitung. */
function mailFields(data) {
  return {
    creator: { mapValue: { fields: {
      type: string('extern'),
      name: string(data.senderName?.trim() || data.senderEmail),
      email: string(data.senderEmail)
    } } },
    source: string('email'), senderEmail: string(data.senderEmail),
    senderName: string(data.senderName || ''), mailMessageId: string(data.mailMessageId),
    deduplicationKey: string(data.deduplicationKey),
    emailSubject: string(data.emailSubject || ''),
    gmailMessageId: string(data.gmailMessageId),
    emailBody: string(data.emailBody)
  };
}

/** Erstellt das Ticket nur, falls seine stabile ID noch nicht existiert. */
function ticketWrite(data, taskId, now) {
  const taskName = 'projects/YOUR_FIREBASE_PROJECT/databases/(default)/documents/tasks/' + taskId;
  const fields = { ...boardFields(data, now), ...mailFields(data) };
  return { update: { name: taskName, fields }, currentDocument: { exists: false } };
}

/** Wandelt einen reservierten Platz in ein abgeschlossenes Ticket um. */
function counterWrite(counter, { reserved, completed }) {
  return { update: { name: counter.name, fields: {
        reservedCount: { integerValue: String(reserved - 1) },
        completedCount: { integerValue: String(completed + 1) }
      } }, updateMask: { fieldPaths: ['reservedCount', 'completedCount'] },
      currentDocument: { updateTime: counter.updateTime } };
}

/** Markiert die unveränderte Mailreservierung als abgeschlossen. */
function reservationWrite(data, taskId, now) {
  return { update: { name: data.reservation.name, fields: {
        status: string('completed'), quotaState: string('completed'), taskId: string(taskId),
        completedAt: { timestampValue: now }
      } }, updateMask: { fieldPaths: ['status', 'quotaState', 'taskId', 'completedAt'] },
      currentDocument: { updateTime: data.reservation.updateTime } };
}

/** Bündelt alle drei Änderungen in einem Commit für genau eine Mail. */
return $input.all().map((item, index) => {
  const counter = item.json;
  const data = $('Ticketdaten gültig?').itemMatching(index).json;
  const quota = readQuota(counter, data);
  checkReservation(counter, data);
  const now = $now.toUTC().toISO();
  const taskId = 'mail-' + data.reservationId;
  const writes = [ticketWrite(data, taskId, now), counterWrite(counter, quota), reservationWrite(data, taskId, now)];
  return { json: { taskId, commit: { writes } }, pairedItem: { item: index } };
});

/** Gibt genau einen reservierten Platz frei und aktualisiert die Mail im selben versionsgeschützten Commit. */
return $input.all().map((item, index) => {
  const counter = item.json;
  const failure = $('Ungültige Ticketdaten vorbereiten').itemMatching(index).json;
  const count = Number(counter.fields?.reservedCount?.integerValue);
  if (!Number.isSafeInteger(count) || count < 1 || failure.quota?.state !== 'reserved') {
    throw new Error('Tagesplatz kann nicht freigegeben werden: Reservierung oder Zähler ungültig.');
  }
  if (counter.name !== failure.quota.counterName || !counter.updateTime || !failure.reservationUpdateTime) {
    throw new Error('Tagesplatz kann nicht freigegeben werden: Dokumentversion fehlt.');
  }
  return { json: { ...failure, commit: { writes: [
    { update: { name: counter.name, fields: { reservedCount: { integerValue: String(count - 1) } } },
      updateMask: { fieldPaths: ['reservedCount'] }, currentDocument: { updateTime: counter.updateTime } },
    { update: { name: failure.reservation.name, fields: {
        status: { stringValue: 'manual_review' }, quotaState: { stringValue: 'released' },
        failedAt: { timestampValue: failure.failedAt }, errorMessage: { stringValue: failure.errorMessage }
      } }, updateMask: { fieldPaths: ['status', 'quotaState', 'failedAt', 'errorMessage'] },
      currentDocument: { updateTime: failure.reservationUpdateTime } }
  ] } }, pairedItem: { item: index } };
});

/** Reads Gmail's case-insensitive headers, including mailparser's raw header lines. */
function readHeader(mail, name) {
  const entry = Object.entries(mail.headers ?? {}).find(([key]) => key.toLowerCase() === name);
  return String(entry?.[1] ?? '').replace(new RegExp('^' + name + ':\\s*', 'i'), '').trim();
}

/** Detects vacation agents and delivery reports without rejecting human reply subjects. */
function isAutomatic(mail) {
  const auto = readHeader(mail, 'auto-submitted').split(';')[0].trim().toLowerCase();
  const mime = readHeader(mail, 'content-type');
  const sender = mail.from?.value?.[0]?.address ?? readHeader(mail, 'from');
  return (auto !== '' && auto !== 'no')
    || ['x-autoreply', 'x-autorespond'].some(key => /^(?!no$|false$|0$).+/i.test(readHeader(mail, key)))
    || /report-type\s*=\s*"?delivery-status\b|^message\/(?:global-)?delivery-status\b/i.test(mime)
    || readHeader(mail, 'return-path') === '<>'
    || /(?:^|<)(?:mailer-daemon|postmaster)@/i.test(sender);
}

return $input.all().flatMap((item, index) =>
  isAutomatic(item.json) ? [] : [{ ...item, pairedItem: { item: index } }]
);

/** Builds one automatic acknowledgement for each successfully saved ticket. */
return $input.all().map((item, index) => {
  const recipient = $('Ticketdaten gültig?').itemMatching(index).json.senderEmail;
  const taskId = item.json.taskId;
  if (!/^[^\s@<>,;:]+@[^\s@<>,;:]+$/.test(recipient) || !/^mail-[a-f0-9]{64}$/.test(taskId)) {
    throw new Error('Empfänger oder Ticket-ID der Bestätigung ungültig.');
  }
  const lines = [
    'To: ' + recipient,
    'Subject: Join - Eingang deiner Anfrage',
    'Auto-Submitted: auto-replied',
    'X-Auto-Response-Suppress: All',
    'MIME-Version: 1.0',
    'Content-Type: text/plain; charset=UTF-8',
    '',
    'Deine Anfrage wurde in Join aufgenommen. Ticket-ID: ' + taskId
  ];
  return {json: {raw: Buffer.from(lines.join('\r\n')).toString('base64url')}, pairedItem: {item: index}};
});

